  --cinema-bg-rgb: 14, 16, 20;                   /* RGB tuple for translucent scrims */
  --cinema-scrim-dual:
    linear-gradient(90deg, rgba(14, 16, 20, 0.95) 0%, rgba(14, 16, 20, 0.70) 32%, rgba(14, 16, 20, 0) 62%),
    linear-gradient(0deg, #0e1014 30%, rgba(14, 16, 20, 0.60) 48%, rgba(14, 16, 20, 0) 70%);
  --cinema-scrim-scrolled: rgba(14, 16, 20, 0.88);
  --cinema-scrim-scrolled-gradient: linear-gradient(180deg, rgba(14, 16, 20, 0.35) 0%, rgba(14, 16, 20, 0.55) 100%);
  --cinema-blur-filter: blur(28px) saturate(1.4) brightness(0.7);

  /* Cinema Card & Component Surfaces */
  --cinema-surface-card: #26292f;                /* Google TV card container background */
  --cinema-surface-dialog: #202124;              /* Side sheet, detail overlay & modal surface */
  --cinema-surface-tile: #303134;                /* Inner dialog tile surface */
  --cinema-surface-pill: rgba(60, 64, 67, 0.55); /* Google TV top pill nav container */
  --cinema-surface-pill-active: rgba(232, 234, 237, 0.18); /* Active tab highlight */
  --cinema-surface-chip: #3c4043;                /* Filter chips & secondary controls */
  --cinema-accent-blue: #8ab4f8;                 /* Google TV profile avatar / selected highlight */

  /* Cinema Typography Hierarchy */
  --cinema-font-family: "Google Sans", Roboto, "LG Smart UI", Inter, Helvetica, Arial, sans-serif;
  --cinema-text-primary: #e8eaed;                /* Crisp light-gray high-emphasis text */
  --cinema-text-secondary: #bdc1c6;              /* Metadata, descriptions, secondary chips */
  --cinema-text-muted: #9aa0a6;                  /* Captions, timestamps, third-tier text */
  --cinema-text-subtle: #80868b;                 /* Footnotes and dim hints */
  --cinema-text-inverse: #202124;                /* Inverted dark text on focused white pills */

  /* Cinema Radii */
  --cinema-radius-card: 14px;                    /* Exact Google TV card radius */
  --cinema-radius-chip: 28px;                    /* Floating action pills & filters */
  --cinema-radius-tab: 30px;                     /* Top bar tab buttons */
  --cinema-radius-sheet: 32px;                   /* Quick settings & side sheets */

  /* Cinema Virtual Keyboard Dimensions */
  --cinema-key-width: 72px;
  --cinema-key-height: 64px;
  --cinema-key-radius: 14px;
  --cinema-key-bg: #3c4043;

  /* Cinema Spatial Remote Focus Halo Standards (10-Foot Experience) */
  --cinema-focus-border-color: #FFFFFF;
  --cinema-focus-border-width: 5px;
  --cinema-focus-border: 5px solid #FFFFFF;
  --cinema-focus-glow: rgba(149, 255, 80, 0.65);
  --cinema-focus-shadow: 0 0 0 5px #FFFFFF, 0 0 28px rgba(149, 255, 80, 0.65);
  --cinema-focus-shadow-pure: 0 0 0 5px #FFFFFF, 0 12px 30px rgba(0, 0, 0, 0.60);
  --cinema-focus-scale: 1.08;
  --cinema-focus-scale-card: 1.10;
  --cinema-focus-transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.2s ease, border-color 0.2s ease;

  /* Cinema Animation Easing Curves */
  --cinema-ease-decel: cubic-bezier(0.2, 0.8, 0.2, 1);
  --cinema-ease-standard: cubic-bezier(0.2, 0, 0, 1);

  /* Semantic Theme Mappings (Forward Compatibility) */
  --color-bg-cinema: var(--cinema-bg-base);
  --color-surface-card-cinema: var(--cinema-surface-card);
  --color-surface-dialog-cinema: var(--cinema-surface-dialog);
  --color-surface-tile-cinema: var(--cinema-surface-tile);
  --color-text-cinema-primary: var(--cinema-text-primary);
  --color-text-cinema-secondary: var(--cinema-text-secondary);
  --color-text-cinema-muted: var(--cinema-text-muted);
}

